package portreuse

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

// Demonstrates the mechanism behind the flake: the port of a closed
// httptest.Server can be handed straight back out to a later server.
func TestPortReuseAfterClose(t *testing.T) {
	dead := map[string]bool{}
	for range 200 {
		s := httptest.NewServer(http.HandlerFunc(func(http.ResponseWriter, *http.Request) {}))
		url := s.URL
		s.Close()
		dead[url] = true
	}

	live := []*httptest.Server{}
	defer func() {
		for _, s := range live {
			s.Close()
		}
	}()
	collisions := 0
	for range 200 {
		s := httptest.NewServer(http.HandlerFunc(func(http.ResponseWriter, *http.Request) {}))
		live = append(live, s)
		if dead[s.URL] {
			collisions++
			t.Logf("collision: live server bound %s, which a closed server still hands out as dead", s.URL)
		}
	}
	t.Logf("collisions: %d/200", collisions)
	if collisions == 0 {
		t.Log("no collision this run (timing-dependent)")
	}
}

