// Demonstrates the mechanism behind the flake: the port of a closed
// httptest.Server can be handed straight back out to a later server.
// Interleaved close/open, which is what parallel tests actually do.
func TestPortReuseInterleaved(t *testing.T) {
	dead := map[string]bool{}
	live := []*httptest.Server{}
	defer func() {
		for _, s := range live {
			s.Close()
		}
	}()

	collisions := 0
	for range 3000 {
		d := httptest.NewServer(http.HandlerFunc(func(http.ResponseWriter, *http.Request) {}))
		durl := d.URL
		d.Close()
		dead[durl] = true

		s := httptest.NewServer(http.HandlerFunc(func(http.ResponseWriter, *http.Request) {}))
		if dead[s.URL] {
			collisions++
			if collisions <= 3 {
				t.Logf("collision: live server bound %s, still treated as dead elsewhere", s.URL)
			}
		}
		live = append(live, s)
	}
	t.Logf("collisions: %d/3000", collisions)
}

