// Victim: keep-alive requests over the shared DefaultTransport, the same
// pool TestRoundTripper_TokenCacheReusesExchanged reuses between its two
// requests.
func TestZZReproVictim(t *testing.T) {
	t.Parallel()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		io.Copy(io.Discard, r.Body) //nolint:errcheck // test
		w.WriteHeader(http.StatusOK)
	}))
	defer srv.Close()

	client := &http.Client{Transport: http.DefaultTransport}
	deadline := time.Now().Add(20 * time.Second)
	n := 0
	for time.Now().Before(deadline) {
		n++
		req, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, srv.URL, strings.NewReader("")) //nolint:errcheck // test
		resp, err := client.Do(req)
		if err != nil {
			t.Fatalf("request %d failed after %d successes: %v", n, n-1, err)
		}
		io.Copy(io.Discard, resp.Body) //nolint:errcheck // test
		resp.Body.Close()
	}
	t.Logf("%d requests, no failure", n)
}

